function formatSessionLine(s) {
  let line = '';
  if (s.subject) line += `[${s.subject}] `;
  line += formatDate(s.date);
  if (s.start_time) line += ` ${s.start_time}`;
  if (s.end_time) line += `–${s.end_time}`;
  const zh = SESSION_STATUS_ZH[s.status] || s.status || '—';
  line += `（${zh}）`;
  return line;
}

/** Split long strings to fit canvas width (variable-width font). */
function wrapLinesByMeasure(ctx, text, maxW) {
  const lines = [];
  let rest = text;
  while (rest.length) {
    if (ctx.measureText(rest).width <= maxW) {
      lines.push(rest);
      break;
    }
    let lo = 1;
    let hi = rest.length;
    let best = 1;
    while (lo <= hi) {
      const mid = Math.floor((lo + hi) / 2);
      if (ctx.measureText(rest.slice(0, mid)).width <= maxW) {
        best = mid;
        lo = mid + 1;
      } else {
        hi = mid - 1;
      }
    }
    lines.push(rest.slice(0, best));
    rest = rest.slice(best).trimStart();
  }
  return lines;
}

function buildAttendedLines(ctx, sessions, maxW) {
  const out = [];
  for (const s of sessions) {
    wrapLinesByMeasure(ctx, formatSessionLine(s), maxW).forEach((l) => out.push(l));
  }
  return out;
}

